import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  Linking,
  KeyboardAvoidingView,
  Platform,
  Modal,
  ScrollView,
  useWindowDimensions,
  Animated,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
  addDoc,
  updateDoc,
  setDoc,
  serverTimestamp,
} from 'firebase/firestore';
import { LinearGradient } from 'expo-linear-gradient';
import { MaterialCommunityIcons, MaterialIcons } from '@expo/vector-icons';
import { onAuthStateChanged } from 'firebase/auth';
import BottomActionBar from '../components/BottomActionBar';
import { firestore, auth } from '../services/firebaseConfig';
import { confirmAction } from '../utils/confirmAction';

const UIDS_PERMITIDOS = [
  'MZJwf2P2i3QYefTrN4lMDRCp0En2',
  '8ddAG6JqQJTmgiIvQjfctxFIc9U2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'qWkygznNc0gpLOJuZ7zf4ZldzCJ2',
  'DibIuShhIqbApUpHAIKSG8w2dE02',
];

interface Ensaio {
  id?: string;
  data: string;
  horário: string;
  observacoes: string;
  criadoEm: any;
}

interface Devocional {
  id?: string;
  link: string;
  criadoEm: any;
  interacaoVersao?: string;
}

type ReacaoDevocional = 'fogo' | 'coracao' | 'amem';

interface InteracaoDevocional {
  uid: string;
  reacao: ReacaoDevocional;
  versao: string;
  atualizadoEm?: any;
}

const skeuoShadow = {
  shadowColor: '#000',
  shadowOffset: { width: 0, height: 10 },
  shadowOpacity: 0.28,
  shadowRadius: 16,
  elevation: 10,
};

function formatData(text: string) {
  let cleaned = text.replace(/\D/g, '');
  if (cleaned.length > 2) cleaned = cleaned.slice(0, 2) + '/' + cleaned.slice(2);
  if (cleaned.length > 5) cleaned = cleaned.slice(0, 5) + '/' + cleaned.slice(5, 9);
  return cleaned.slice(0, 10);
}

function formatHorario(text: string) {
  let cleaned = text.replace(/\D/g, '');
  if (cleaned.length > 2) cleaned = cleaned.slice(0, 2) + ':' + cleaned.slice(2, 4);
  return cleaned.slice(0, 5);
}

function isYoutubeLink(link: string) {
  return /^(https?:\/\/)?(www\.)?(youtube\.com|youtu\.be)\//.test(link);
}

function getYoutubeEmbedUrl(link: string) {
  try {
    const url = new URL(link);
    let videoId = '';

    if (url.hostname.includes('youtu.be')) {
      videoId = url.pathname.replace('/', '');
    } else if (url.pathname.includes('/shorts/')) {
      videoId = url.pathname.split('/shorts/')[1]?.split('/')[0] || '';
    } else if (url.pathname.includes('/embed/')) {
      videoId = url.pathname.split('/embed/')[1]?.split('/')[0] || '';
    } else {
      videoId = url.searchParams.get('v') || '';
    }

    return videoId ? `https://www.youtube.com/embed/${videoId}?enablejsapi=1` : link;
  } catch {
    return link;
  }
}

const GradientButton = ({ onPress, children, style = {}, variant = 'primary' }: any) => (
  <TouchableOpacity onPress={onPress} activeOpacity={0.85} style={[styles.buttonWrap, style]}>
    <LinearGradient
      colors={variant === 'danger' ? ['#FF6B6B', '#D9365E'] : ['#FFB84D', '#FF7A3D']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.gradientBtn}
    >
      <Text style={styles.gradientBtnText}>{children}</Text>
    </LinearGradient>
  </TouchableOpacity>
);

export default function EnsaiosScreen() {
  const navigation = useNavigation();
  const { width } = useWindowDimensions();
  const isSmallScreen = width < 390;
  const [ensaios, setEnsaios] = useState<Ensaio[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [novaData, setNovaData] = useState('');
  const [novoHorario, setNovoHorario] = useState('');
  const [novasObs, setNovasObs] = useState('');
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [editData, setEditData] = useState('');
  const [editHorario, setEditHorario] = useState('');
  const [editObs, setEditObs] = useState('');
  const [devocional, setDevocional] = useState<Devocional | null>(null);
  const [interacoesDevocional, setInteracoesDevocional] = useState<InteracaoDevocional[]>([]);
  const [novoLink, setNovoLink] = useState('');
  const [editandoDevocional, setEditandoDevocional] = useState(false);
  const [modalAviso, setModalAviso] = useState(false);
  const [modalDevocional, setModalDevocional] = useState(false);
  const [devocionalAssistido, setDevocionalAssistido] = useState(false);
  const reacaoAnimacoes = React.useRef<Record<ReacaoDevocional, Animated.Value>>({
    fogo: new Animated.Value(1),
    coracao: new Animated.Value(1),
    amem: new Animated.Value(1),
  }).current;

  useEffect(() => {
    const loops = (Object.keys(reacaoAnimacoes) as ReacaoDevocional[]).map((reacao, index) => {
      const animacao = reacaoAnimacoes[reacao];

      const loop = Animated.loop(
        Animated.sequence([
          Animated.delay(index * 180),
          Animated.timing(animacao, {
            toValue: 1.14,
            duration: 520,
            useNativeDriver: true,
          }),
          Animated.spring(animacao, {
            toValue: 1,
            friction: 4,
            tension: 80,
            useNativeDriver: true,
          }),
          Animated.delay(1400),
        ]),
      );

      loop.start();
      return loop;
    });

    return () => loops.forEach(loop => loop.stop());
  }, [reacaoAnimacoes]);

  useEffect(() => {
    const ensaiosQuery = query(collection(firestore, 'ensaios'), orderBy('criadoEm', 'desc'));
    const devocionalQuery = query(collection(firestore, 'devocional'), orderBy('criadoEm', 'desc'));

    const unsubAuth = onAuthStateChanged(auth, usuario => {
      setUidAtual(usuario?.uid ?? null);
    });

    const unsubEnsaios = onSnapshot(ensaiosQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(docSnap => ({
        id: docSnap.id,
        ...docSnap.data(),
      }));
      setEnsaios(data as Ensaio[]);
      setLoading(false);
    }, () => setLoading(false));

    const unsubDevocional = onSnapshot(devocionalQuery, (querySnapshot) => {
      const docs = querySnapshot.docs.map(docSnap => ({
        id: docSnap.id,
        ...docSnap.data(),
      }));
      setDevocional((docs[0] as Devocional) || null);
    });

    return () => {
      unsubAuth();
      unsubEnsaios();
      unsubDevocional();
    };
  }, []);

  useEffect(() => {
    if (!devocional?.id) {
      setInteracoesDevocional([]);
      return;
    }

    const interacoesRef = collection(firestore, 'devocional', devocional.id, 'interacoes');
    const unsubInteracoes = onSnapshot(interacoesRef, (querySnapshot) => {
      setInteracoesDevocional(querySnapshot.docs.map(docSnap => docSnap.data() as InteracaoDevocional));
    });

    return () => unsubInteracoes();
  }, [devocional?.id]);

  useEffect(() => {
    setDevocionalAssistido(false);
  }, [devocional?.id, devocional?.interacaoVersao, devocional?.link]);

  useEffect(() => {
    if (Platform.OS !== 'web') return;

    const handleYoutubeMessage = (event: any) => {
      let data = event?.data;

      if (typeof data === 'string') {
        try {
          data = JSON.parse(data);
        } catch {
          return;
        }
      }

      if (data?.event === 'onStateChange' && data?.info === 1) {
        setDevocionalAssistido(true);
      }
    };

    window.addEventListener('message', handleYoutubeMessage);
    return () => window.removeEventListener('message', handleYoutubeMessage);
  }, []);

  const podeEditar = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  const excluirEnsaio = async (id: string) => {
    if (!podeEditar) return;
    confirmAction({
      title: 'Excluir devocional',
      message: 'Tem certeza que deseja excluir este devocional?',
      onConfirm: async () => {
        try {
          await auth.currentUser?.getIdToken(true);
          await deleteDoc(doc(firestore, 'ensaios', id));
          setEnsaios(prev => prev.filter(e => e.id !== id));
        } catch (error: any) {
          console.log('Erro ao excluir devocional:', error);
        }
      },
    });
  };

  const handleCriarEnsaio = async () => {
    if (!podeEditar) {
      Alert.alert('Sem permissão', 'Seu usuário não tem permissão para criar postagens do devocional.');
      return;
    }

    if (!novaData.trim() || !novoHorario.trim()) {
      Alert.alert('Atenção', 'Preencha a data e o horário.');
      return;
    }
    try {
      await addDoc(collection(firestore, 'ensaios'), {
        data: novaData,
        horário: novoHorario,
        observacoes: novasObs,
        criadoEm: new Date(),
      });
      setNovaData('');
      setNovoHorario('');
      setNovasObs('');
      setModalAviso(false);
    } catch {
      Alert.alert('Erro', 'Não foi possível criar o devocional.');
    }
  };

  const handleEditarEnsaio = (ensaio: Ensaio) => {
    if (!podeEditar) return;

    setEditandoId(ensaio.id!);
    setEditData(ensaio.data);
    setEditHorario(ensaio.horário);
    setEditObs(ensaio.observacoes);
  };

  const handleSalvarEdicao = async () => {
    if (!podeEditar) {
      Alert.alert('Sem permissão', 'Seu usuário não tem permissão para editar postagens do devocional.');
      return;
    }

    if (!editData.trim() || !editHorario.trim() || !editandoId) {
      Alert.alert('Atenção', 'Preencha a data e o horário.');
      return;
    }
    try {
      await updateDoc(doc(firestore, 'ensaios', editandoId), {
        data: editData,
        horário: editHorario,
        observacoes: editObs,
      });
      setEditandoId(null);
      setEditData('');
      setEditHorario('');
      setEditObs('');
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o devocional.');
    }
  };

  const handleSalvarDevocional = async () => {
    if (!podeEditar) {
      Alert.alert('Sem permissão', 'Seu usuário não tem permissão para salvar o devocional.');
      return;
    }

    if (!novoLink.trim()) {
      Alert.alert('Atenção', 'Informe o link do devocional.');
      return;
    }
    try {
      const interacaoVersao = `${Date.now()}`;
      if (devocional && devocional.id) {
        await updateDoc(doc(firestore, 'devocional', devocional.id), {
          link: novoLink,
          interacaoVersao,
        });
      } else {
        await addDoc(collection(firestore, 'devocional'), {
          link: novoLink,
          interacaoVersao,
          criadoEm: new Date(),
        });
      }
      setEditandoDevocional(false);
      setNovoLink('');
      setModalDevocional(false);
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o devocional.');
    }
  };

  const handleDataChange = (text: string) => setNovaData(formatData(text));
  const handleHorarioChange = (text: string) => setNovoHorario(formatHorario(text));
  const handleEditDataChange = (text: string) => setEditData(formatData(text));
  const handleEditHorarioChange = (text: string) => setEditHorario(formatHorario(text));

  const renderItem = ({ item }: { item: Ensaio }) => (
    <LinearGradient
      colors={['#FFB84D', '#43E97B', '#46D7FF']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.ensaioBorder}
    >
      <LinearGradient
        colors={['#151C3C', '#222047', '#2D2146']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.ensaioCard}
      >
        <View style={styles.cardGlow} />
        {editandoId === item.id && podeEditar ? (
          <>
            <TextInput style={styles.input} value={editData} onChangeText={handleEditDataChange} placeholder="Data (ex: 10/06/2025)" placeholderTextColor="#BFD7FF" keyboardType="numeric" maxLength={10} />
            <TextInput style={styles.input} value={editHorario} onChangeText={handleEditHorarioChange} placeholder="Horário (ex: 19:30)" placeholderTextColor="#BFD7FF" keyboardType="numeric" maxLength={5} />
            <TextInput style={[styles.input, styles.textArea]} value={editObs} onChangeText={setEditObs} placeholder="Observações" placeholderTextColor="#BFD7FF" multiline />
            <View style={styles.actionRow}>
              <GradientButton onPress={handleSalvarEdicao} style={{ flex: 1, marginRight: 8 }}>Salvar</GradientButton>
              <GradientButton onPress={() => setEditandoId(null)} style={{ flex: 1, marginLeft: 8 }}>Cancelar</GradientButton>
            </View>
          </>
        ) : (
          <>
            <View style={styles.ensaioHeader}>
              <View style={styles.ensaioIconBadge}>
                <MaterialCommunityIcons name="book-open-page-variant" size={23} color="#111827" />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={styles.avisoTítulo}>Devocional marcado</Text>
                <Text style={styles.avisoData}>{item.criadoEm?.toDate ? item.criadoEm.toDate().toLocaleString() : ''}</Text>
              </View>
            </View>

            <View style={styles.infoGrid}>
              <View style={styles.infoChip}>
                <MaterialIcons name="event" size={17} color="#67E8F9" />
                <Text style={styles.infoChipLabel}>Data</Text>
                <Text style={styles.infoChipValue}>{item.data}</Text>
              </View>
              <View style={styles.infoChip}>
                <MaterialIcons name="schedule" size={17} color="#72F2A4" />
                <Text style={styles.infoChipLabel}>Horário</Text>
                <Text style={styles.infoChipValue}>{item.horário}</Text>
              </View>
            </View>

            {item.observacoes ? (
              <View style={styles.obsBox}>
                <MaterialCommunityIcons name="bullhorn-outline" size={18} color="#FFB84D" />
                <Text style={styles.avisoMensagem}>{item.observacoes}</Text>
              </View>
            ) : null}

            {podeEditar && (
              <View style={styles.actionRow}>
                <GradientButton onPress={() => handleEditarEnsaio(item)} style={{ flex: 1, marginRight: 8 }}>Editar</GradientButton>
                <GradientButton onPress={() => excluirEnsaio(item.id!)} style={{ flex: 1, marginLeft: 8 }} variant="danger">Excluir</GradientButton>
              </View>
            )}
          </>
        )}
      </LinearGradient>
    </LinearGradient>
  );

  const abrirDevocional = () => {
    if (devocional?.link) {
      setDevocionalAssistido(true);
      Linking.openURL(devocional.link);
    } else {
      Alert.alert('Devocional', 'Nenhum devocional foi cadastrado.');
    }
  };

  const versaoDevocional = devocional?.interacaoVersao || devocional?.link || '';
  const interacoesDaVersao = interacoesDevocional.filter(interacao => interacao.versao === versaoDevocional);
  const minhaReacao = interacoesDaVersao.find(interacao => interacao.uid === uidAtual)?.reacao;
  const totalAssistiram = interacoesDaVersao.length;
  const totalPorReacao = {
    fogo: interacoesDaVersao.filter(interacao => interacao.reacao === 'fogo').length,
    coracao: interacoesDaVersao.filter(interacao => interacao.reacao === 'coracao').length,
    amem: interacoesDaVersao.filter(interacao => interacao.reacao === 'amem').length,
  };

  const reagirDevocional = async (reacao: ReacaoDevocional) => {
    if (!uidAtual) {
      Alert.alert('Devocional', 'Entre novamente na sua conta para registrar sua interação.');
      return;
    }
    if (!devocional?.id || !versaoDevocional) return;
    if (minhaReacao === reacao) {
      return;
    }

    try {
      Animated.sequence([
        Animated.spring(reacaoAnimacoes[reacao], {
          toValue: 1.34,
          friction: 3,
          tension: 140,
          useNativeDriver: true,
        }),
        Animated.spring(reacaoAnimacoes[reacao], {
          toValue: 1,
          friction: 4,
          tension: 100,
          useNativeDriver: true,
        }),
      ]).start();
      setDevocionalAssistido(true);

      await setDoc(doc(firestore, 'devocional', devocional.id, 'interacoes', uidAtual), {
        uid: uidAtual,
        reacao,
        versao: versaoDevocional,
        atualizadoEm: serverTimestamp(),
      });
    } catch (error) {
      console.log('Erro ao reagir ao devocional:', error);
      Alert.alert('Erro', 'Não foi possível registrar sua interação.');
    }
  };

  return (
    <LinearGradient
      colors={['#0B1630', '#161934', '#241A3D']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.gradientBg}
    >
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        keyboardVerticalOffset={80}
      >
        <View style={{ flex: 1 }}>
          <View style={styles.topNavRow}>
            <TouchableOpacity style={styles.topNavBtn} onPress={() => navigation.navigate('Inicio')} activeOpacity={0.85}>
              <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
            </TouchableOpacity>
            <View style={styles.titleWrap}>
              <View style={styles.titleIconWrap}>
                <MaterialCommunityIcons name="book-open-page-variant" size={24} color="#111827" />
              </View>
              <Text style={styles.title}>Devocional</Text>
            </View>
            <TouchableOpacity style={styles.topNavBtn} onPress={() => navigation.goBack()} activeOpacity={0.85}>
              <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
            </TouchableOpacity>
          </View>

          <View style={styles.container}>
            <ScrollView
              style={styles.conteudoScroll}
              contentContainerStyle={[styles.conteudoScrollInner, isSmallScreen && styles.conteudoScrollInnerCompacto]}
              showsVerticalScrollIndicator={false}
            >
              <LinearGradient
                colors={devocional?.link ? ['#FFB84D', '#FF7A3D', '#E84D88'] : ['#46D7FF', '#43E97B', '#FFB84D']}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.devocionalHeroBorder}
              >
                <LinearGradient
                  colors={['#172044', '#211B3D']}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.devocionalHero}
                >
                  <View style={styles.devocionalHeroTop}>
                    <View style={styles.devocionalIconPulse}>
                      <MaterialCommunityIcons name="book-open-page-variant" size={26} color="#111827" />
                    </View>
                    <View style={{ flex: 1 }}>
                      <Text style={styles.devocionalEyebrow}>Devocional da semana</Text>
                      <Text style={styles.devocionalTitle}>
                        {devocional?.link ? 'Prepare seu coração com este devocional❤️‍🔥' : 'Devocional ainda não cadastrado'}
                      </Text>
                    </View>
                  </View>
                  <Text style={styles.devocionalSubtitle}>
                    {devocional?.link
                      ? 'Assista ao vídeo e chegue alinhado para servir com intenção.'
                      : 'Quando um link for salvo, ele aparece aqui em destaque para todos.'}
                  </Text>

                  {devocional?.link && Platform.OS === 'web' && isYoutubeLink(devocional.link) ? (
                    <View style={styles.videoFrame}>
                      {React.createElement('iframe', {
                        src: getYoutubeEmbedUrl(devocional.link),
                        title: 'Devocional',
                        id: 'devocional-youtube',
                        allow: 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture',
                        allowFullScreen: true,
                        onLoad: (event: any) => {
                          event?.target?.contentWindow?.postMessage(JSON.stringify({ event: 'listening', id: 'devocional-youtube' }), '*');
                        },
                        style: { width: '100%', height: '100%', border: 0, borderRadius: 14 },
                      })}
                    </View>
                  ) : (
                    <TouchableOpacity style={styles.youtubePlayBtn} onPress={abrirDevocional} activeOpacity={0.85}>
                      <View style={styles.youtubeIconBox}>
                        <MaterialIcons name="play-arrow" size={22} color="#fff" />
                      </View>
                      <Text style={styles.youtubeText}>{devocional?.link ? 'Assistir agora' : 'Aguardando link'}</Text>
                    </TouchableOpacity>
                  )}

                  {devocional?.link ? (
                    <View style={styles.devocionalInteracoes}>
                      <View style={styles.devocionalInteracoesHeader}>
                        <Text style={styles.devocionalInteracoesTitle}>Interações</Text>
                        <Text style={styles.devocionalAssistiram}>{totalAssistiram} assistiram</Text>
                      </View>
                      <View style={styles.reacaoRow}>
                        <TouchableOpacity
                          style={[styles.reacaoButton, minhaReacao === 'fogo' && styles.reacaoButtonAtiva]}
                          onPress={() => reagirDevocional('fogo')}
                          activeOpacity={0.85}
                        >
                          <Animated.Text style={[styles.reacaoEmoji, { transform: [{ scale: reacaoAnimacoes.fogo }] }]}>🔥</Animated.Text>
                          <Text style={styles.reacaoCount}>{totalPorReacao.fogo}</Text>
                        </TouchableOpacity>
                        <TouchableOpacity
                          style={[styles.reacaoButton, minhaReacao === 'coracao' && styles.reacaoButtonAtiva]}
                          onPress={() => reagirDevocional('coracao')}
                          activeOpacity={0.85}
                        >
                          <Animated.Text style={[styles.reacaoEmoji, { transform: [{ scale: reacaoAnimacoes.coracao }] }]}>❤️</Animated.Text>
                          <Text style={styles.reacaoCount}>{totalPorReacao.coracao}</Text>
                        </TouchableOpacity>
                        <TouchableOpacity
                          style={[styles.reacaoButton, minhaReacao === 'amem' && styles.reacaoButtonAtiva]}
                          onPress={() => reagirDevocional('amem')}
                          activeOpacity={0.85}
                        >
                          <Animated.Text style={[styles.reacaoEmoji, { transform: [{ scale: reacaoAnimacoes.amem }] }]}>🙌🏼</Animated.Text>
                          <Text style={styles.reacaoCount}>{totalPorReacao.amem}</Text>
                        </TouchableOpacity>
                      </View>
                    </View>
                  ) : null}
                </LinearGradient>
              </LinearGradient>

              <View style={styles.sectionHeader}>
                <Text style={styles.sectionTitle}>Devocionais agendados</Text>
                <Text style={styles.sectionCount}>{ensaios.length}</Text>
              </View>

              <View style={styles.listaEnsaios}>
                {loading ? (
                  <ActivityIndicator size="large" color="#FFB84D" style={{ marginTop: 24 }} />
                ) : ensaios.length === 0 ? (
                  <Text style={styles.emptyText}>Nenhum devocional cadastrado.</Text>
                ) : (
                  ensaios.map(item => renderItem({ item }))
                )}
              </View>
            </ScrollView>
          </View>

          <Modal visible={modalAviso} transparent animationType="fade" onRequestClose={() => setModalAviso(false)}>
            <View style={styles.modalBg}>
              <LinearGradient colors={['#252B55', '#171B38']} style={styles.modalBox}>
                <Text style={styles.modalTitle}>Agendar Devocional</Text>
                <TextInput style={styles.input} placeholder="Data (ex: 10/06/2025)" value={novaData} onChangeText={handleDataChange} placeholderTextColor="#BFD7FF" keyboardType="numeric" maxLength={10} />
                <TextInput style={styles.input} placeholder="Horario (ex: 19:30)" value={novoHorario} onChangeText={handleHorarioChange} placeholderTextColor="#BFD7FF" keyboardType="numeric" maxLength={5} />
                <TextInput style={[styles.input, styles.textArea]} placeholder="Observacoes" value={novasObs} onChangeText={setNovasObs} placeholderTextColor="#BFD7FF" multiline />
                <GradientButton onPress={handleCriarEnsaio} style={{ marginTop: 8 }}>Salvar</GradientButton>
                <GradientButton onPress={() => setModalAviso(false)} style={{ marginTop: 8 }}>Cancelar</GradientButton>
              </LinearGradient>
            </View>
          </Modal>

          <Modal visible={modalDevocional} transparent animationType="fade" onRequestClose={() => setModalDevocional(false)}>
            <View style={styles.modalBg}>
              <LinearGradient colors={['#252B55', '#171B38']} style={styles.modalBox}>
                <Text style={styles.modalTitle}>Link do Devocional</Text>
                <TextInput style={styles.input} placeholder="Link do devocional" value={novoLink} onChangeText={setNovoLink} placeholderTextColor="#BFD7FF" />
                <GradientButton onPress={handleSalvarDevocional} style={{ marginTop: 8 }}>Salvar</GradientButton>
                <GradientButton onPress={() => setModalDevocional(false)} style={{ marginTop: 8 }}>Cancelar</GradientButton>
              </LinearGradient>
            </View>
          </Modal>
        </View>
      </KeyboardAvoidingView>

      {podeEditar && (
        <BottomActionBar
          onNovoEnsaio={() => setModalAviso(true)}
          onNovoDevocional={() => setModalDevocional(true)}
          onPlayDevocional={abrirDevocional}
          onEditarDevocional={() => {
            setEditandoDevocional(true);
            setNovoLink(devocional?.link || '');
            setModalDevocional(true);
          }}
          skeuoShadow={skeuoShadow}
        />
      )}
    </LinearGradient>
  );
}

