export default function TelaCriarEscala(): JSX.Element {
  const navigation = useNavigation();
  const [escala, setEscala] = useState<Escala>(estadoInicial);
  const [corCamiseta, setCorCamiseta] = useState('#FFFFFF');
  const [corCalcaSaia, setCorCalcaSaia] = useState('#111827');
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [calendarioAberto, setCalendarioAberto] = useState(false);
  const [campoIntegranteAberto, setCampoIntegranteAberto] = useState<keyof Escala | null>(null);
  const [integrantes, setIntegrantes] = useState<Integrante[]>([]);
  const [mesCalendario, setMesCalendario] = useState(() => {
    const hoje = getHojeDate();
    return new Date(hoje.getFullYear(), hoje.getMonth(), 1);
  });

  // ✅ Declarada antes de ser usada
  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  // ==========================================================
  // ✅ FUNÇÕES DE NOTIFICAÇÃO
  // ==========================================================
  const pedirPermissaoNotificacoes = async () => {
    if (Platform.OS === 'web') return;
    const { status } = await Notifications.requestPermissionsAsync({
      ios: { allowAlert: true, allowBadge: true, allowSound: true },
    });
    if (status !== 'granted') console.log('⚠️ Permissão de notificação negada');
  };

  const enviarNotificacaoNovaEscala = async (
    dataEscala: string,
    responsavel: string,
    ehAtualizacao: boolean
  ) => {
    try {
      await Notifications.scheduleNotificationAsync({
        content: {
          title: ehAtualizacao ? '🔄 ESCALA ATUALIZADA!' : '📅 NOVA ESCALA CRIADA!',
          body: `Escala para ${dataEscala} — Responsável: ${responsavel}`,
          sound: true,
          badge: 1,
        },
        trigger: null,
      });
      console.log(`✅ Notificação (${ehAtualizacao ? 'atualização' : 'criação'}) enviada!`);
    } catch (erro) {
      console.log('❌ Erro ao enviar notificação:', erro);
    }
  };

  useEffect(() => {
    setUidAtual(auth.currentUser?.uid ?? null);
    pedirPermissaoNotificacoes();

    let fotosLocal: Record<string, string> = {};
    AsyncStorage.getItem('fotosUsuarios')
      .then(valor => { if (valor) fotosLocal = JSON.parse(valor); })
      .catch(() => {});

    const unsubscribe = onSnapshot(collection(db, 'presencas'), snapshot => {
      const fotosBanco: Record<string, string> = {};
      snapshot.docs.forEach(docSnap => {
        const dados = docSnap.data();
        Object.entries(dados.fotosUsuarios || {}).forEach(([nome, foto]) => {
          if (typeof foto === 'string' && foto) fotosBanco[nome] = foto;
        });
      });
      const fotosAtuais = { ...FOTOS_PADRAO, ...fotosBanco, ...fotosLocal };
      setIntegrantes(
        NOMES_USUARIOS.map(nome => ({
          nome,
          foto: fotosAtuais[nome] || `https://ui-avatars.com/api/?name=${encodeURIComponent(nome)}`,
        }))
      );
    }, error => {
      console.log('Erro ao carregar integrantes:', error);
    });
    return () => unsubscribe();
  }, []);

  const handleChange = (campo: keyof Escala, valor: string) => {
    if (campo === 'data') {
      let cleaned = valor.replace(/\D/g, '');
      if (cleaned.length > 8) cleaned = cleaned.slice(0, 8);
      let formatted = cleaned;
      if (cleaned.length > 4) formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2, 4)}/${cleaned.slice(4)}`;
      else if (cleaned.length > 2) formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2)}`;
      setEscala(prev => ({ ...prev, [campo]: formatted }));
    } else {
      setEscala(prev => ({ ...prev, [campo]: valor }));
    }
  };

  const abrirCalendario = () => {
    const dataBase = dataParaDate(escala.data);
    setMesCalendario(new Date(dataBase.getFullYear(), dataBase.getMonth(), 1));
    setCalendarioAberto(true);
  };

  const fecharCalendario = () => setCalendarioAberto(false);

  const mudarMesCalendario = (direcao: -1 | 1) => {
    setMesCalendario(prev => new Date(prev.getFullYear(), prev.getMonth() + direcao, 1));
  };

  const selecionarDataCalendario = (data: Date) => {
    setEscala(prev => ({ ...prev, data: dateParaData(data) }));
    fecharCalendario();
  };

  const abrirSeletorIntegrante = (campo: keyof Escala) => {
    if (!permitido) return;
    setCampoIntegranteAberto(campo);
  };

  const selecionarIntegrante = (integrante: Integrante) => {
    if (!campoIntegranteAberto) return;
    setEscala(prev => ({ ...prev, [campoIntegranteAberto]: integrante.nome }));
    setCampoIntegranteAberto(null);
  };

  const obterIntegranteSelecionado = (nome: string) => {
    if (!nome) return null;
    return integrantes.find(i => i.nome === nome) || {
      nome,
      foto: `https://ui-avatars.com/api/?name=${encodeURIComponent(nome)}`,
    };
  };

  const salvarEscala = async () => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) {
      Alert.alert('Acesso negado', 'Você não tem permissão para criar/editar escalas.');
      return;
    }
    if (!escala.data || !escala.responsavel) {
      Alert.alert('Erro', 'Preencha pelo menos Data e Responsável.');
      return;
    }

    const idDoc = escala.data.replace(/\//g, '-');
    const uniformeSelecionado = { corCamiseta, corCalcaSaia };

    try {
      const escalaRef = doc(db, 'escalas', idDoc);

      // ✅ VERIFICA SE JÁ EXISTE → NOVA ou ATUALIZAÇÃO
      const docSnapshot = await getDoc(escalaRef);
      const ehAtualizacao = docSnapshot.exists();

      // Salva ou atualiza a escala
      await setDoc(escalaRef, {
        ...escala,
        uniforme: uniformeSelecionado,
        atualizadoEm: new Date(),
        criadoEm: ehAtualizacao ? docSnapshot.data()?.criadoEm : new Date(),
      }, { merge: true });

      // Atualiza dados de uniforme
      await setDoc(doc(db, 'meta', 'uniformeCulto'), {
        ...uniformeSelecionado,
        atualizadoEm: new Date(),
        atualizadoPor: uidAtual,
        origem: 'escala',
        escalaId: idDoc,
      }, { merge: true });

      // ✅ ENVIA NOTIFICAÇÃO — NOVA ou ATUALIZAÇÃO
      await enviarNotificacaoNovaEscala(escala.data, escala.responsavel, ehAtualizacao);

      // Atualiza contador e badge
      const metaRef = doc(db, 'meta', 'escalas');
      try {
        await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
      } catch {
        try {
          await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
        } catch (err) {
          console.log('Erro ao atualizar contador:', err);
        }
      }

      try {
        const cur = await AsyncStorage.getItem('nova_escala');
        const num = cur ? parseInt(cur, 10) || 0 : 0;
        const novo = num + 1;
        await AsyncStorage.setItem('nova_escala', String(novo));
        await Notifications.setBadgeCountAsync(novo);
      } catch {
        console.log('Não foi possível atualizar badge');
      }

      Alert.alert(
        'Sucesso',
        ehAtualizacao
          ? 'Escala ATUALIZADA com sucesso! 🔔 Notificação enviada.'
          : 'Escala CRIADA com sucesso! 🔔 Notificação enviada.'
      );
      navigation.goBack();
    } catch (error) {
      console.error('Erro ao salvar escala:', error);
      Alert.alert('Erro', 'Não foi possível salvar a escala.');
    }
  };

  const formatarLabel = (key: keyof Escala): string => {
    switch (key) {
      case 'data': return 'Data';
      case 'responsavel': return 'Responsável';
      case 'violao': return 'Violão';
      case 'teclado': return 'Teclado';
      case 'bateria': return 'Bateria';
      case 'guitarra': return 'Guitarra';
      case 'contrabaixo': return 'Contrabaixo';
      case 'vocal': return 'Vocal';
      case 'backVocal1': return 'Back Vocal 1';
      case 'backVocal2': return 'Back Vocal 2';
      case 'backVocal3': return 'Back Vocal 3';
      case 'backVocal4': return 'Back Vocal 4';
      case 'som': return 'Som';
      case 'projecao': return 'Projeção';
      case 'midia1': return 'Mídia 1';
      case 'midia2': return 'Mídia 2';
      case 'midia3': return 'Mídia 3';
      case 'midia4': return 'Mídia 4';
      default: return String(key).charAt(0).toUpperCase() + String(key).slice(1);
    }
  };

  const handlePressIn = () => {
    Animated.spring(saveAnim, { toValue: 0.96, useNativeDriver: true }).start();
  };
  const handlePressOut = () => {
    Animated.spring(saveAnim, { toValue: 1, friction: 3, tension: 40, useNativeDriver: true }).start();
  };

  // Animação de alto relevo para o botão
  const saveAnim = React.useRef(new Animated.Value(1)).current;

  return (
    <LinearGradient colors={['#0B1630', '#151936', '#241A3D']} style={styles.bg}>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
          <View style={styles.topBar}>
            <TouchableOpacity style={[styles.topButton, styles.topButtonLeft]} onPress={() => navigation.navigate('Inicio')} activeOpacity={0.85}>
              <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
            </TouchableOpacity>
            <View style={styles.topTitleContainer}>
              <View style={styles.titleIconWrap}>
                <MaterialCommunityIcons name="calendar-plus" size={23} color="#111827" />
              </View>
              <Text style={styles.topTitle}>Nova Escala</Text>
            </View>
            <TouchableOpacity style={[styles.topButton, styles.topButtonRight]} onPress={() => navigation.goBack()} activeOpacity={0.85}>
              <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
            </TouchableOpacity>
          </View>

          <View style={styles.card}>
            {Object.keys(escala).map((chave) => {
              const campo = chave as keyof Escala;
              return (
                <NeumorphicContainer key={campo} style={styles.inputGroup}>
                  <View style={styles.labelRow}>
                    <View style={styles.fieldIconWrap}>
                      <MaterialCommunityIcons name={iconesPorCampoNovo[campo]} size={19} color="#111827" />
                    </View>
                    <Text style={styles.label}>{formatarLabel(campo)}</Text>
                  </View>
                  {campo === 'data' ? (
                    <TouchableOpacity
                      style={styles.dateInputButton}
                      onPress={abrirCalendario}
                      disabled={!permitido}
                      activeOpacity={0.85}
                    >
                      <Text style={[styles.dateInputText, !escala.data && styles.dateInputPlaceholder]}>
                        {escala.data || 'Selecionar data'}
                      </Text>
                    </TouchableOpacity>
                  ) : (
                    <TouchableOpacity
                      style={styles.memberInputButton}
                      onPress={() => abrirSeletorIntegrante(campo)}
                      disabled={!permitido}
                      activeOpacity={0.85}
                    >
                      {obterIntegranteSelecionado(escala[campo]) ? (
                        <View style={styles.memberSelectedRow}>
                          <Image
                            source={{ uri: obterIntegranteSelecionado(escala[campo])?.foto }}
                            style={styles.memberSelectedPhoto}
                          />
                          <Text style={styles.memberSelectedName} numberOfLines={1}>
                            {obterIntegranteSelecionado(escala[campo])?.nome}
                          </Text>
                        </View>
                      ) : (
                        <Text style={styles.memberPlaceholder}>Selecionar integrante</Text>
                      )}
                    </TouchableOpacity>
                  )}
                </NeumorphicContainer>
              );
            })}

            <NeumorphicContainer style={styles.uniformeBox}>
              <View style={styles.labelRow}>
                <MaterialIcons name="checkroom" size={22} color="#ff9800" style={{ marginRight: 8 }} />
                <Text style={styles.label}>Uniforme do culto</Text>
              </View>

              <Text style={styles.uniformeLabel}>Cor da camiseta</Text>
              <View style={styles.coresLinha}>
                {CORES_UNIFORME.map(cor => (
                  <TouchableOpacity
                    key={`camiseta-${cor}`}
                    style={[styles.corOpcao, { backgroundColor: cor }, corCamiseta === cor && styles.corOpcaoSelecionada]}
                    onPress={() => setCorCamiseta(cor)}
                    disabled={!permitido}
                    activeOpacity={0.8}
                  />
                ))}
              </View>

              <Text style={styles.uniformeLabel}>Cor da calça ou saia</Text>
              <View style={styles.coresLinha}>
                {CORES_UNIFORME.map(cor => (
                  <TouchableOpacity
                    key={`calça-${cor}`}
                    style={[styles.corOpcao, { backgroundColor: cor }, corCalcaSaia === cor && styles.corOpcaoSelecionada]}
                    onPress={() => setCorCalcaSaia(cor)}
                    disabled={!permitido}
                    activeOpacity={0.8}
                  />
                ))}
              </View>
            </NeumorphicContainer>

            <Animated.View style={{ transform: [{ scale: saveAnim }] }}>
              <TouchableOpacity
                style={[styles.saveButton, !permitido && styles.saveButtonDisabled]}
                onPress={salvarEscala}
                disabled={!permitido}
                onPressIn={handlePressIn}
                onPressOut={handlePressOut}
                activeOpacity={0.85}
              >
                <Text style={styles.saveButtonText}>Salvar Escala</Text>
              </TouchableOpacity>
            </Animated.View>

            {!permitido && (
              <Text style={styles.permissãoAviso}>
                Apenas usuários autorizados podem criar escalas.
              </Text>
            )}
          </View>
        </ScrollView>

        <Modal transparent visible={calendarioAberto} animationType="fade" onRequestClose={fecharCalendario}>
          <View style={styles.calendarioOverlay}>
            <LinearGradient colors={['#252B55', '#171B38']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.calendarioModal}>
              <View style={styles.calendarioHeader}>
                <TouchableOpacity style={styles.calendarioNavBtn} onPress={() => mudarMesCalendario(-1)}>
                  <Text style={styles.calendarioNavText}>{'<'}</Text>
                </TouchableOpacity>
                <View style={styles.calendarioTítuloBox}>
                  <Text style={styles.calendarioTítulo}>{MESES[mesCalendario.getMonth()]}</Text>
                  <Text style={styles.calendarioAno}>{mesCalendario.getFullYear()}</Text>
                </View>
                <TouchableOpacity style={styles.calendarioNavBtn} onPress={() => mudarMesCalendario(1)}>
                  <Text style={styles.calendarioNavText}>{'>'}</Text>
                </TouchableOpacity>
              </View>
              <View style={styles.calendarioSemana}>
                {DIAS_SEMANA.map((dia, idx) => (
                  <Text key={`${dia}-${idx}`} style={styles.calendarioSemanaTexto}>{dia}</Text>
                ))}
              </View>
              <View style={styles.calendarioGrid}>
                {montarDiasCalendario(mesCalendario).map((data, idx) => {
                  const dataFormatada = data ? dateParaData(data) : '';
                  const selecionada = !!data && dataFormatada === escala.data;
                  const hoje = !!data && dataFormatada === dateParaData(getHojeDate());
                  return (
                    <TouchableOpacity
                      key={`${dataFormatada || 'vazio'}-${idx}`}
                      style={[
                        styles.calendarioDia,
                        !data && styles.calendarioDiaVazio,
                        hoje && styles.calendarioDiaHoje,
                        selecionada && styles.calendarioDiaSelecionado,
                      ]}
                      disabled={!data}
                      onPress={() => data && selecionarDataCalendario(data)}
                      activeOpacity={0.82}
                    >
                      <Text style={[
                        styles.calendarioDiaTexto,
                        hoje && styles.calendarioDiaTextoHoje,
                        selecionada && styles.calendarioDiaTextoSelecionado,
                      ]}>
                        {data ? data.getDate() : ''}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
              <View style={styles.calendarioAcoes}>
                <TouchableOpacity style={styles.calendarioCancelar} onPress={fecharCalendario}>
                  <Text style={styles.calendarioCancelarTexto}>Cancelar</Text>
                </TouchableOpacity>
                <TouchableOpacity style={styles.calendarioHojeBtn} onPress={() => selecionarDataCalendario(getHojeDate())}>
                  <Text style={styles.calendarioHojeTexto}>Hoje</Text>
                </TouchableOpacity>
              </View>
            </LinearGradient>
          </View>
        </Modal>

        <Modal transparent visible={!!campoIntegranteAberto} animationType="fade" onRequestClose={() => setCampoIntegranteAberto(null)}>
          <View style={styles.integrantesOverlay}>
            <LinearGradient colors={['#252B55', '#171B38']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.integrantesModal}>
              <View style={styles.integrantesHeader}>
                <Text style={styles.integrantesTítulo}>
                  {campoIntegranteAberto ? formatarLabel(campoIntegranteAberto) : 'Selecionar integrante'}
                </Text>
                <TouchableOpacity style={styles.integrantesFechar} onPress={() => setCampoIntegranteAberto(null)}>
                  <MaterialIcons name="close" size={22} color="#EAF7FF" />
                </TouchableOpacity>
              </View>
              <ScrollView style={styles.integrantesLista} contentContainerStyle={styles.integrantesListaContent}>
                {integrantes.length > 0 ? (
                  integrantes.map(integrante => (
                    <TouchableOpacity
                      key={integrante.nome}
                      style={styles.integranteOpcao}
                      onPress={() => selecionarIntegrante(integrante)}
                      activeOpacity={0.84}
                    >
                      <Image source={{ uri: integrante.foto }} style={styles.integranteFoto} />
                      <Text style={styles.integranteNome} numberOfLines={1}>{integrante.nome}</Text>
                    </TouchableOpacity>
                  ))
                ) : (
                  <Text style={styles.integrantesVazio}>Nenhum integrante cadastrado em Presença.</Text>
                )}
              </ScrollView>
            </LinearGradient>
          </View>
        </Modal>
      </KeyboardAvoidingView>
    </LinearGradient>
  );
}

